"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ANALYTICS,
  COHORTS,
  DESTINATIONS,
  HEADLINE,
  NATIONAL_PATH,
  REASON_MIX,
  SOURCE_NOTE,
  SLUG,
  VIZ_MARKERS,
  fmtK,
  fmtM,
  fmtPct,
  fmtPp,
  sortedByPp,
  statesByStatus,
  type ExpansionStatus,
} from "@/data/uninsurance-by-state-after-medicaid-unwinding-2026-data";

// viz-types: state pp-change bars, national composed path,
// destination pie, medicaid-loss vs pp scatter, cohort bars,
// reason stacked bars | layout: default
// smoke-marker: Uninsured-rate change after unwinding

type ViewId = "ladder" | "path" | "destinations" | "scatter" | "cohorts";
type StatusFilter = "all" | ExpansionStatus;
type LadderLens = "pp" | "uninsured2024" | "medicaid";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";
const SLATE = "#64748b";

const STATUS_COLORS: Record<string, string> = {
  "coverage-gap": ROSE,
  "non-expansion": AMBER,
  expansion: TEAL,
};

const DEST_COLORS = [TEAL, ROSE, INDIGO, SKY, AMBER, SLATE];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div
      className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"
      data-viz={SLUG}
    >
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  options,
  value,
  onChange,
}: {
  options: { id: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((o) => (
        <button
          key={o.id}
          type="button"
          onClick={() => onChange(o.id)}
          className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
            value === o.id
              ? "bg-slate-900 text-white"
