type StatusFilter = "all" | ExpansionStatus;
type LadderLens = "pp" | "uninsured2024" | "medicaid";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";
const SLATE = "#64748b";

const STATUS_COLORS: Record<string, string> = {
  "coverage-gap": ROSE,
  "non-expansion": AMBER,
  expansion: TEAL,
