                />
                <Line
                  yAxisId="enroll"
                  type="monotone"
                  dataKey="marketplaceM"
                  name="Marketplace (M)"
                  stroke={INDIGO}
                  strokeWidth={2}
                  dot={false}
                />
                <Line
                  yAxisId="rate"
                  type="monotone"
                  dataKey="uninsuredPct"
                  name="Uninsured %"
                  stroke={ROSE}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "destinations" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Who absorbed the churn"
