            <div className="h-[340px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={DESTINATIONS}
                    dataKey="sharePct"
                    nameKey="destination"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={110}
                    paddingAngle={2}
                  >
                    {DESTINATIONS.map((d, i) => (
                      <Cell key={d.destination} fill={DEST_COLORS[i % DEST_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v: number, _n, item) => [
                      `${v}% (${fmtM(item?.payload?.millions ?? 0)})`,
                      item?.payload?.destination,
